    public static Profile profile(String preset) {
        return switch(preset) {
            case "Fabric","Fabric_HiPen","Fabric_MedPen","GenericSoft","Rubber","Snow","Tyre" -> GENERICSOFT;
            case "Asphalt","Concrete","Stone","Tile" -> CONCRETE;
            case "Cardboard","Cardboard_MedPen","WoodThick","WoodThick_MedPen","WoodThin" -> WOOD;
            case "Chainfence","Grate","MetalThick","MetalThick_HiPen","MetalThick_LowPen","MetalThick_MedPen","MetalThin" -> METAL;
            case "Plastic" -> PLASTIC;
            case "Glass" -> GLASS;
            case "GrassHigh","GrassLow","Pebbles","Pebbles_MedPen","Soil","SoilForest" -> SOIL;
            default -> null;
        };
    }
